def head(title): return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daily Ingest Dossier — {e(title)} — {DATE}</title><meta name="lib:group" content="report"><meta name="lib:date" content="{DATE}"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Newsreader:opsz,wght@6..72,400;6..72,600&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">{CSS}</head><body><main><header>{LOGO}<h1>Daily Ingest Dossier — {e(title)}</h1><div class="date">{DATE} · Adaptive research brief</div>'
def report(lane):
 items=lane['items']; w=max(720,len(items)*220); nodes=''.join(f'<g transform="translate({20+i*220},55)"><rect width="184" height="72" rx="8" fill="#f8fafc" stroke="#cbd5e1"/><text x="92" y="29" text-anchor="middle" class="label">{e(x[0][:23])}</text><text x="92" y="49" text-anchor="middle" class="label">{e(x[3])}</text></g>' for i,x in enumerate(items))
