 out=head(lane['title'])+f'<p>{e(lane["readout"])}</p></header><section><article class="card"><h2>Signal map</h2><div class="badges"><span class="badge good">fresh signal</span><span class="badge">coverage gap</span></div>{svg}<div class="callout"><strong>Why this lane:</strong> {e(lane["rationale"])}</div></article>'
 for n,x in enumerate(items,1):
  title,url,typ,pub,what,use,caveat,action=x
  out+=f'<article class="card"><div class="badges"><span class="badge good">{e(typ)}</span><span class="badge">{e(pub)}</span></div><h2>{n}. <a href="{e(url)}">{e(title)}</a></h2><div class="grid"><div class="fact"><strong>What it is</strong><br>{e(what)}</div><div class="fact"><strong>Buildn / client use</strong><br>{e(use)}</div></div><p><strong>Why useful now:</strong> {e(lane["rationale"])}</p><div class="callout"><strong>Caveat:</strong> {e(caveat)}</div><p><strong>Follow-up action:</strong> {e(action)}</p></article>'
 out+='<article class="card"><h2>Use-case matrix</h2><table><thead><tr><th>Theme</th><th>Buildn OS</th><th>Client work</th><th>Agent workflows</th><th>Personal leverage</th></tr></thead><tbody><tr><td>Evaluate</td><td>Sandbox first</td><td>Offer a bounded pilot</td><td>Set an acceptance test</td><td>Save a repeatable checklist</td></tr><tr><td>Operate</td><td>Scope authority</td><td>Keep named ownership</td><td>Log evidence and actions</td><td>Prefer reversible changes</td></tr></tbody></table></article><article class="card top"><h2>Top actions</h2><ol>'+''.join(f'<li><a href="{e(x[1])}">{e(x[0])}</a> — {e(x[7])}</li>' for x in items[:3])+'</ol></article><article class="card"><h2>Source trail</h2><ul>'+''.join(f'<li><a href="{e(x[1])}">{e(x[0])}</a> <span class="date">({e(x[2])}, {e(x[3])})</span></li>' for x in items)+'</ul></article></section></main></body></html>'
 return out
